INSERT INTO questions (section, part, sort_order, payload) VALUES ('listening', 'A', 0, $${"kind": "listening", "part": "A", "partTitle": "Part A — Short Conversations", "script": [{"s": "W", "t": "Did you finish the chemistry lab report?"}, {"s": "M", "t": "I barely started. The procedure section is taking forever."}], "id": "LIS-A-01", "stem": "What does the man imply about the lab report?", "options": ["He has finished it.", "He finds it difficult.", "He lost the instructions.", "He will skip the class."], "answer": 1, "explanation": "Pria itu berkata ia baru mulai (I barely started) dan bagian prosedurnya memakan waktu sangat lama (taking forever), artinya ia menganggap laporan itu sulit dan menyita waktu. Pilihan A salah karena ia belum selesai. Pilihan C salah karena tidak ada instruksi yang hilang. Pilihan D salah karena ia tidak berniat membolos."}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('listening', 'A', 1, $${"kind": "listening", "part": "A", "partTitle": "Part A — Short Conversations", "script": [{"s": "M", "t": "The library closes at nine tonight, right?"}, {"s": "W", "t": "Actually, it's open until midnight during finals week."}], "id": "LIS-A-02", "stem": "What does the woman tell the man?", "options": ["The library opens at nine.", "The man should study at home.", "The library hours are extended this week.", "The library is closed for finals."], "answer": 2, "explanation": "Wanita itu mengoreksi pria tersebut: perpustakaan buka sampai tengah malam selama minggu ujian (finals week), jadi jam bukanya diperpanjang. Pilihan A salah karena jam sembilan adalah jam tutup menurut dugaan pria itu, bukan jam buka. Pilihan B tidak disebutkan. Pilihan D salah karena perpustakaan justru buka lebih lama."}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('listening', 'A', 2, $${"kind": "listening", "part": "A", "partTitle": "Part A — Short Conversations", "script": [{"s": "W", "t": "How was the physics midterm?"}, {"s": "M", "t": "Honestly, it was a piece of cake compared to the quizzes."}], "id": "LIS-A-03", "stem": "What does the man mean?", "options": ["He failed the exam.", "The exam was easy.", "He celebrated after the exam.", "The exam was about cooking."], "answer": 1, "explanation": "Ungkapan a piece of cake artinya sangat mudah. Pria itu menganggap ujian tengah semester fisika mudah, apalagi dibanding kuis-kuis sebelumnya. Pilihan A salah karena ia tidak gagal. Pilihan C salah karena tidak ada perayaan. Pilihan D salah karena kue di sini hanya kiasan."}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('listening', 'A', 3, $${"kind": "listening", "part": "A", "partTitle": "Part A — Short Conversations", "script": [{"s": "M", "t": "My printer ran out of ink right before I printed my essay."}, {"s": "W", "t": "You can use mine. It's in my dorm room, and the door's open."}], "id": "LIS-A-04", "stem": "What does the woman offer to do?", "options": ["Buy new ink for the man.", "Print the essay herself.", "Lend him her printer.", "Edit his essay."], "answer": 2, "explanation": "Wanita itu berkata You can use mine (kamu boleh pakai punyaku) dan pintunya terbuka, artinya ia menawarkan pinjam printernya. Pilihan A salah karena ia tidak menawarkan membeli tinta. Pilihan B salah karena ia tidak menawarkan mencetakkan. Pilihan D salah karena tidak ada tawaran mengedit."}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('listening', 'A', 4, $${"kind": "listening", "part": "A", "partTitle": "Part A — Short Conversations", "script": [{"s": "W", "t": "Professor Lane moved the deadline to Friday."}, {"s": "M", "t": "That's a relief. I thought it was due tomorrow."}], "id": "LIS-A-05", "stem": "What does the man imply?", "options": ["He needs more time to finish.", "He finished the assignment early.", "He dislikes Professor Lane.", "He forgot about the assignment."], "answer": 0, "explanation": "Pria itu merasa lega (That's a relief) karena mengira tenggatnya besok, artinya ia butuh tambahan waktu untuk menyelesaikan tugas. Pilihan B salah karena ia belum selesai. Pilihan C salah karena ia tidak mengeluhkan dosennya. Pilihan D salah karena ia ingat tugas itu."}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('listening', 'A', 5, $${"kind": "listening", "part": "A", "partTitle": "Part A — Short Conversations", "script": [{"s": "M", "t": "You look a little pale. Are you okay?"}, {"s": "W", "t": "I'm just a bit under the weather, but I'll be fine for the game."}], "id": "LIS-A-06", "stem": "What does the woman mean?", "options": ["She feels slightly ill.", "She is worried about the weather.", "She will miss the game.", "She is angry at the man."], "answer": 0, "explanation": "Ungkapan under the weather artinya agak tidak enak badan atau sakit ringan. Wanita itu merasa sedikit sakit tetapi tetap akan ikut pertandingan. Pilihan B salah karena ini bukan soal cuaca. Pilihan C salah karena ia bilang akan baik-baik saja untuk pertandingan. Pilihan D salah karena ia tidak marah."}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('listening', 'A', 6, $${"kind": "listening", "part": "A", "partTitle": "Part A — Short Conversations", "script": [{"s": "W", "t": "The history lecture is in Room 204, isn't it?"}, {"s": "M", "t": "No, they switched it to the auditorium. Too many students enrolled."}], "id": "LIS-A-07", "stem": "Where is the history lecture now?", "options": ["In Room 204.", "In the auditorium.", "In the library.", "In the student center."], "answer": 1, "explanation": "Pria itu berkata kuliahnya dipindah (switched) ke auditorium karena terlalu banyak mahasiswa yang mendaftar. Pilihan A adalah lokasi lama. Pilihan C dan D tidak disebutkan."}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('listening', 'A', 7, $${"kind": "listening", "part": "A", "partTitle": "Part A — Short Conversations", "script": [{"s": "M", "t": "Should I start studying for the final now or wait until the weekend?"}, {"s": "W", "t": "I wouldn't put it off if I were you. There's a ton of material."}], "id": "LIS-A-08", "stem": "What does the woman suggest?", "options": ["He should start studying now.", "He should wait until the weekend.", "He should skip the final exam.", "He should change his classes."], "answer": 0, "explanation": "Wanita itu berkata I wouldn't put it off (aku tidak akan menundanya) karena materinya sangat banyak, artinya ia menyarankan pria itu mulai belajar sekarang. Pilihan B justru kebalikan sarannya. Pilihan C dan D tidak disebutkan."}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('listening', 'A', 8, $${"kind": "listening", "part": "A", "partTitle": "Part A — Short Conversations", "script": [{"s": "W", "t": "Did you hear? The cafeteria is giving away free breakfast on Monday."}, {"s": "M", "t": "You don't have to tell me twice!"}], "id": "LIS-A-09", "stem": "What does the man mean?", "options": ["He doesn't believe her.", "He is eager to go.", "He dislikes breakfast.", "He wants more details."], "answer": 1, "explanation": "Ungkapan You don't have to tell me twice berarti langsung setuju dengan antusias tanpa perlu dibujuk, jadi pria itu sangat mau ikut sarapan gratis. Pilihan A salah karena ia percaya. Pilihan C salah karena ia justru tertarik. Pilihan D salah karena ia tidak meminta detail."}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('listening', 'A', 9, $${"kind": "listening", "part": "A", "partTitle": "Part A — Short Conversations", "script": [{"s": "M", "t": "I can't find my notes from yesterday's lecture."}, {"s": "W", "t": "Relax, I took pretty detailed ones. I'll send you a copy tonight."}], "id": "LIS-A-10", "stem": "What will the woman do?", "options": ["Send her notes to the man.", "Attend the lecture again.", "Lend the man her laptop.", "Ask the professor for notes."], "answer": 0, "explanation": "Wanita itu berjanji I'll send you a copy tonight (akan kukirim salinannya malam ini), jadi ia akan mengirim catatan kuliahnya kepada pria itu. Pilihan B salah karena ia tidak mengulang kuliah. Pilihan C salah karena yang dipinjamkan adalah catatan, bukan laptop. Pilihan D salah karena ia tidak meminta ke dosen."}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('listening', 'A', 10, $${"kind": "listening", "part": "A", "partTitle": "Part A — Short Conversations", "script": [{"s": "W", "t": "Are you coming to the movie tonight?"}, {"s": "M", "t": "I wish I could, but I've got to hit the books. Midterms start Monday."}], "id": "LIS-A-11", "stem": "What does the man mean?", "options": ["He will go to the movie.", "He needs to study.", "He lost his textbooks.", "He works at a bookstore."], "answer": 1, "explanation": "Ungkapan hit the books artinya belajar dengan giat. Pria itu tidak bisa ikut nonton karena harus belajar untuk ujian tengah semester. Pilihan A salah karena ia menolak ajakan. Pilihan C salah karena ia tidak kehilangan buku. Pilihan D salah karena ia tidak bekerja di toko buku."}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('listening', 'A', 11, $${"kind": "listening", "part": "A", "partTitle": "Part A — Short Conversations", "script": [{"s": "M", "t": "The bus to downtown leaves every twenty minutes."}, {"s": "W", "t": "Good, we just missed one, so we won't have to wait long."}], "id": "LIS-A-12", "stem": "What does the woman imply?", "options": ["They should take a taxi instead.", "The bus is always late.", "They missed the last bus.", "The next bus will come soon."], "answer": 3, "explanation": "Bus berangkat tiap dua puluh menit dan mereka baru saja ketinggalan satu, jadi bus berikutnya akan segera datang dan mereka tidak perlu menunggu lama. Pilihan A salah karena ia tidak menyarankan taksi. Pilihan B salah karena tidak dibilang bus selalu telat. Pilihan C salah karena masih ada bus berikutnya."}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('listening', 'A', 12, $${"kind": "listening", "part": "A", "partTitle": "Part A — Short Conversations", "script": [{"s": "W", "t": "Your presentation was amazing. How long did you prepare?"}, {"s": "M", "t": "Thanks! Honestly, I threw it together last night."}], "id": "LIS-A-13", "stem": "What does the man imply about his presentation?", "options": ["He prepared it quickly.", "He worked on it for weeks.", "He is unhappy with it.", "He copied someone else's work."], "answer": 0, "explanation": "Ungkapan threw it together artinya mengerjakan sesuatu dengan cepat dan seadanya. Pria itu menyiapkan presentasinya secara kilat semalam. Pilihan B salah karena bukan berminggu-minggu. Pilihan C salah karena ia tidak bilang tidak puas. Pilihan D salah karena ia tidak menyontek."}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('listening', 'A', 13, $${"kind": "listening", "part": "A", "partTitle": "Part A — Short Conversations", "script": [{"s": "M", "t": "Is the tutoring center open on weekends?"}, {"s": "W", "t": "Only on Saturdays, from ten to two."}], "id": "LIS-A-14", "stem": "When is the tutoring center open on weekends?", "options": ["All weekend.", "On Sundays only.", "On Saturdays from ten to two.", "Only on weekdays."], "answer": 2, "explanation": "Wanita itu menjawab jelas: hanya hari Sabtu, pukul sepuluh sampai dua. Pilihan A salah karena tidak sepanjang akhir pekan. Pilihan B salah karena bukan hari Minggu. Pilihan D salah karena Sabtu termasuk akhir pekan."}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('listening', 'A', 14, $${"kind": "listening", "part": "A", "partTitle": "Part A — Short Conversations", "script": [{"s": "W", "t": "This math problem set is due at midnight, and I'm only halfway done."}, {"s": "M", "t": "Want to work on it together at my place? Two heads are better than one."}], "id": "LIS-A-15", "stem": "What does the man suggest?", "options": ["Starting over alone.", "Asking the professor for an extension.", "Skipping the assignment.", "Working on the problems together."], "answer": 3, "explanation": "Pria itu mengajak mengerjakan soal bersama (work on it together) dan menambahkan peribahasa two heads are better than one yang artinya kerja berdua lebih baik. Pilihan A, B, dan C tidak sesuai dengan tawarannya."}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('listening', 'A', 15, $${"kind": "listening", "part": "A", "partTitle": "Part A — Short Conversations", "script": [{"s": "M", "t": "The new economics textbook costs an arm and a leg."}, {"s": "W", "t": "Tell me about it. I had to sell my old books to afford it."}], "id": "LIS-A-16", "stem": "What does the man mean about the textbook?", "options": ["It is very expensive.", "It is heavy to carry.", "It is difficult to read.", "It is out of stock."], "answer": 0, "explanation": "Ungkapan costs an arm and a leg artinya harganya sangat mahal. Wanita itu pun setuju sampai harus menjual buku lamanya. Pilihan B salah karena bukan soal berat. Pilihan C salah karena bukan soal sulit dibaca. Pilihan D salah karena bukunya tersedia, hanya mahal."}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('listening', 'A', 16, $${"kind": "listening", "part": "A", "partTitle": "Part A — Short Conversations", "script": [{"s": "W", "t": "Do you know where Professor Chen's office hours are posted?"}, {"s": "M", "t": "On her door, I think. Or check the course website."}], "id": "LIS-A-17", "stem": "Where can the woman find the office hours?", "options": ["On the professor's door or the course website.", "In the library.", "At the registrar's office.", "In the textbook."], "answer": 0, "explanation": "Pria itu menyebut dua tempat: di pintu ruangan dosen (on her door) atau di situs web mata kuliah. Pilihan B, C, dan D tidak disebutkan."}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('listening', 'A', 17, $${"kind": "listening", "part": "A", "partTitle": "Part A — Short Conversations", "script": [{"s": "M", "t": "The field trip to the botanical garden is still on for Saturday?"}, {"s": "W", "t": "The forecast says heavy rain all weekend, so don't hold your breath."}], "id": "LIS-A-18", "stem": "What does the woman imply?", "options": ["The trip will probably be canceled.", "The trip is definitely happening.", "She dislikes botanical gardens.", "The weather forecast is unreliable."], "answer": 0, "explanation": "Ungkapan don't hold your breath artinya jangan terlalu berharap. Karena prakiraan menyebut hujan lebat sepanjang akhir pekan, wanita itu menyiratkan karyawisata kemungkinan besar batal. Pilihan B kebalikan maksudnya. Pilihan C salah karena ia tidak bilang benci. Pilihan D salah karena ia justru mengacu pada prakiraan itu."}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('listening', 'A', 18, $${"kind": "listening", "part": "A", "partTitle": "Part A — Short Conversations", "script": [{"s": "W", "t": "I aced the chemistry quiz!"}, {"s": "M", "t": "No way! I barely passed. You must have studied all night."}], "id": "LIS-A-19", "stem": "What can be inferred about the woman's quiz result?", "options": ["She cheated on the quiz.", "She failed the quiz.", "She hasn't taken it yet.", "She got a perfect score."], "answer": 3, "explanation": "Kata aced artinya mendapat nilai sempurna atau sangat tinggi. Pria itu kaget dan menduga wanita itu belajar semalaman. Pilihan A salah karena tidak ada indikasi menyontek. Pilihan B salah karena ia justru sukses. Pilihan C salah karena kuisnya sudah dikerjakan."}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('listening', 'A', 19, $${"kind": "listening", "part": "A", "partTitle": "Part A — Short Conversations", "script": [{"s": "M", "t": "My laptop keeps freezing during online lectures."}, {"s": "W", "t": "Have you tried clearing the cache? That usually does the trick."}], "id": "LIS-A-20", "stem": "What does the woman suggest?", "options": ["Skipping the online lectures.", "Clearing the browser cache.", "Buying a new laptop.", "Calling the professor."], "answer": 1, "explanation": "Wanita itu menyarankan membersihkan cache (clearing the cache) dan berkata that usually does the trick yang artinya biasanya berhasil. Pilihan A salah karena ia tidak menyarankan bolos. Pilihan C salah karena tidak disarankan beli laptop baru. Pilihan D salah karena tidak ada saran menelepon dosen."}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('listening', 'A', 20, $${"kind": "listening", "part": "A", "partTitle": "Part A — Short Conversations", "script": [{"s": "W", "t": "Can you believe the concert tickets sold out in ten minutes?"}, {"s": "M", "t": "I know. I was stuck in the virtual waiting room the whole time."}], "id": "LIS-A-21", "stem": "What does the man imply?", "options": ["He bought tickets early.", "He attended the concert.", "He failed to get tickets.", "He dislikes concerts."], "answer": 2, "explanation": "Pria itu berkata ia terjebak di ruang tunggu virtual (virtual waiting room) sepanjang waktu, artinya ia tidak berhasil membeli tiket sebelum habis. Pilihan A salah karena ia tidak dapat tiket. Pilihan B salah karena ia tidak menonton. Pilihan D salah karena ia justru ingin menonton."}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('listening', 'A', 21, $${"kind": "listening", "part": "A", "partTitle": "Part A — Short Conversations", "script": [{"s": "M", "t": "I heard the campus gym is closed for renovations."}, {"s": "W", "t": "Great. Just when I finally built a routine."}], "id": "LIS-A-22", "stem": "What does the woman imply?", "options": ["She is happy about the closure.", "She never exercises.", "She works at the gym.", "She is annoyed by the timing."], "answer": 3, "explanation": "Kata Great di sini bernada sarkastis: tepat saat ia akhirnya punya rutinitas olahraga, gym malah tutup. Jadi ia kesal dengan waktunya. Pilihan A salah karena ia tidak senang. Pilihan B salah karena ia justru rutin berolahraga. Pilihan C salah karena ia pengunjung, bukan pegawai."}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('listening', 'A', 22, $${"kind": "listening", "part": "A", "partTitle": "Part A — Short Conversations", "script": [{"s": "W", "t": "Your roommate seems nice. How long have you known him?"}, {"s": "M", "t": "Since orientation week. We clicked right away."}], "id": "LIS-A-23", "stem": "What does the man mean by \"clicked\"?", "options": ["They argued at first.", "They became friends quickly.", "They met on the internet.", "They share the same class."], "answer": 1, "explanation": "Ungkapan clicked dalam konteks pertemanan artinya langsung akrab atau cocok. Pria itu langsung berteman baik dengan teman sekamarnya sejak minggu orientasi. Pilihan A salah karena mereka tidak bertengkar. Pilihan C salah karena mereka bertemu saat orientasi. Pilihan D salah karena tidak dibahas."}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('listening', 'A', 23, $${"kind": "listening", "part": "A", "partTitle": "Part A — Short Conversations", "script": [{"s": "M", "t": "The Wi-Fi in the dorm keeps dropping during my video calls."}, {"s": "W", "t": "Same here. The IT desk said they're installing new routers next week."}], "id": "LIS-A-24", "stem": "What will happen next week?", "options": ["New routers will be installed.", "The Wi-Fi will be shut off.", "The dorm will be closed.", "Video calls will be banned."], "answer": 0, "explanation": "Wanita itu berkata bagian IT akan memasang router baru minggu depan (installing new routers next week). Pilihan B salah karena Wi-Fi tidak dimatikan. Pilihan C salah karena asrama tidak ditutup. Pilihan D salah karena panggilan video tidak dilarang."}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('listening', 'A', 24, $${"kind": "listening", "part": "A", "partTitle": "Part A — Short Conversations", "script": [{"s": "W", "t": "Are you signing up for the debate club?"}, {"s": "M", "t": "I'm on the fence. My schedule is already packed."}], "id": "LIS-A-25", "stem": "What does the man mean?", "options": ["He already joined the club.", "He will join next year.", "He hasn't decided yet.", "He dislikes debates."], "answer": 2, "explanation": "Ungkapan on the fence artinya ragu-ragu atau belum memutuskan. Jadwalnya yang padat membuatnya belum bisa memutuskan ikut klub debat. Pilihan A salah karena ia belum gabung. Pilihan B salah karena ia tidak bilang tahun depan. Pilihan D salah karena ia tidak bilang benci debat."}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('listening', 'A', 25, $${"kind": "listening", "part": "A", "partTitle": "Part A — Short Conversations", "script": [{"s": "M", "t": "Did the study group meet yesterday?"}, {"s": "W", "t": "We pushed it to Thursday. Half the group had a lab conflict."}], "id": "LIS-A-26", "stem": "Why was the study group postponed?", "options": ["The room was locked.", "Nobody wanted to study.", "The tutor canceled.", "Several members had a scheduling conflict."], "answer": 3, "explanation": "Wanita itu berkata pertemuan diundur (pushed) ke hari Kamis karena separuh anggota bentrok dengan jadwal lab (lab conflict). Pilihan A salah karena tidak ada soal ruangan terkunci. Pilihan B salah karena anggotanya mau belajar. Pilihan C salah karena tidak ada tutor yang batal."}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('listening', 'A', 26, $${"kind": "listening", "part": "A", "partTitle": "Part A — Short Conversations", "script": [{"s": "W", "t": "How do I get to the science building from here?"}, {"s": "M", "t": "Go straight past the fountain, then take the second left. You can't miss it."}], "id": "LIS-A-27", "stem": "What is the man doing?", "options": ["Describing a fountain.", "Giving directions.", "Inviting her to his class.", "Complaining about the campus."], "answer": 1, "explanation": "Pria itu memberi petunjuk arah langkah demi langkah: lurus melewati air mancur lalu belok kiri kedua. Pilihan A salah karena air mancur hanya patokan arah. Pilihan C salah karena ia tidak mengajak ke kelas. Pilihan D salah karena ia tidak mengeluh."}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('listening', 'A', 27, $${"kind": "listening", "part": "A", "partTitle": "Part A — Short Conversations", "script": [{"s": "M", "t": "I pulled an all-nighter finishing my portfolio."}, {"s": "W", "t": "You look exhausted. Maybe grab some coffee before the critique."}], "id": "LIS-A-28", "stem": "What does the woman suggest?", "options": ["Skipping the critique session.", "Redoing the portfolio.", "Getting some coffee.", "Going back to sleep."], "answer": 2, "explanation": "Wanita itu menyarankan pria itu minum kopi (grab some coffee) sebelum sesi kritik karena ia terlihat kelelahan setelah begadang (pulled an all-nighter). Pilihan A salah karena ia tidak menyarankan bolos. Pilihan B salah karena portofolionya sudah selesai. Pilihan D salah karena ia tidak menyarankan tidur lagi."}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('listening', 'A', 28, $${"kind": "listening", "part": "A", "partTitle": "Part A — Short Conversations", "script": [{"s": "W", "t": "The professor posts the lecture slides before class."}, {"s": "M", "t": "That helps a lot. I can follow along instead of scribbling notes."}], "id": "LIS-A-29", "stem": "What does the man imply?", "options": ["He never attends class.", "He dislikes the slides.", "He prefers using textbooks.", "The slides make note-taking easier."], "answer": 3, "explanation": "Pria itu berkata slide sangat membantu karena ia bisa mengikuti kuliah tanpa harus mencoret-coret catatan dengan terburu-buru (scribbling notes). Pilihan A salah karena ia hadir di kelas. Pilihan B salah karena ia justru suka slide. Pilihan C salah karena buku teks tidak dibahas."}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('listening', 'A', 29, $${"kind": "listening", "part": "A", "partTitle": "Part A — Short Conversations", "script": [{"s": "M", "t": "Is it true the parking permit fees went up again?"}, {"s": "W", "t": "Yep, by twenty bucks. Highway robbery, if you ask me."}], "id": "LIS-A-30", "stem": "What does the woman think about the fee increase?", "options": ["It is reasonable.", "It is confusing.", "It is illegal.", "It is unfair."], "answer": 3, "explanation": "Ungkapan highway robbery artinya harga yang sangat tidak wajar, seperti dirampok. Wanita itu menganggap kenaikan biaya parkir tidak adil. Pilihan A salah karena ia tidak menganggapnya wajar. Pilihan B salah karena ia tidak bingung. Pilihan C salah karena ia tidak bilang melanggar hukum."}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('listening', 'B', 30, $${"kind": "listening", "part": "B", "partTitle": "Part B — Long Conversations", "script": [{"s": "M", "t": "Thanks for seeing me, Professor Alvarez. I'm thinking of switching my major to environmental science."}, {"s": "W", "t": "That's a big decision. What made you consider the switch?"}, {"s": "M", "t": "Honestly, the biology classes I've taken this year have been the highlight of my schedule."}, {"s": "W", "t": "That's a good sign. Have you looked at the required courses for the major?"}, {"s": "M", "t": "A little. I noticed there's a field research component in the junior year."}, {"s": "W", "t": "Right, two weeks at the coastal research station. Most students say it's the best part."}, {"s": "M", "t": "It sounds amazing, but I'm worried about falling behind on credits."}, {"s": "W", "t": "Many of your biology credits will transfer. Why don't we map out a plan together next week?"}], "id": "LIS-B-01-Q1", "scriptId": "LIS-B-01", "stem": "What is the conversation mainly about?", "options": ["The man's plan to change his major.", "A biology field trip.", "The woman's research project.", "Graduation requirements."], "answer": 0, "explanation": "Seluruh percakapan membahas rencana pria itu pindah jurusan ke environmental science dan kekhawatirannya soal kredit. Pilihan B salah karena riset lapangan hanya satu detail jurusan itu. Pilihan C salah karena bukan proyek si wanita. Pilihan D salah karena syarat kelulusan tidak dibahas."}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('listening', 'B', 31, $${"kind": "listening", "part": "B", "partTitle": "Part B — Long Conversations", "script": [{"s": "M", "t": "Thanks for seeing me, Professor Alvarez. I'm thinking of switching my major to environmental science."}, {"s": "W", "t": "That's a big decision. What made you consider the switch?"}, {"s": "M", "t": "Honestly, the biology classes I've taken this year have been the highlight of my schedule."}, {"s": "W", "t": "That's a good sign. Have you looked at the required courses for the major?"}, {"s": "M", "t": "A little. I noticed there's a field research component in the junior year."}, {"s": "W", "t": "Right, two weeks at the coastal research station. Most students say it's the best part."}, {"s": "M", "t": "It sounds amazing, but I'm worried about falling behind on credits."}, {"s": "W", "t": "Many of your biology credits will transfer. Why don't we map out a plan together next week?"}], "id": "LIS-B-01-Q2", "scriptId": "LIS-B-01", "stem": "According to the woman, what is part of the junior year?", "options": ["An internship abroad.", "Two weeks of field research.", "A teaching assistantship.", "An online course."], "answer": 1, "explanation": "Wanita itu berkata ada dua minggu riset lapangan di stasiun penelitian pesisir (two weeks at the coastal research station) pada tahun ketiga. Pilihan A, C, dan D tidak disebutkan."}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('listening', 'B', 32, $${"kind": "listening", "part": "B", "partTitle": "Part B — Long Conversations", "script": [{"s": "M", "t": "Thanks for seeing me, Professor Alvarez. I'm thinking of switching my major to environmental science."}, {"s": "W", "t": "That's a big decision. What made you consider the switch?"}, {"s": "M", "t": "Honestly, the biology classes I've taken this year have been the highlight of my schedule."}, {"s": "W", "t": "That's a good sign. Have you looked at the required courses for the major?"}, {"s": "M", "t": "A little. I noticed there's a field research component in the junior year."}, {"s": "W", "t": "Right, two weeks at the coastal research station. Most students say it's the best part."}, {"s": "M", "t": "It sounds amazing, but I'm worried about falling behind on credits."}, {"s": "W", "t": "Many of your biology credits will transfer. Why don't we map out a plan together next week?"}], "id": "LIS-B-01-Q3", "scriptId": "LIS-B-01", "stem": "What does the man worry about?", "options": ["The cost of tuition.", "Finding housing.", "Losing academic credits.", "The difficulty of biology classes."], "answer": 2, "explanation": "Pria itu berkata I'm worried about falling behind on credits, artinya ia khawatir tertinggal atau kehilangan kredit akademik jika pindah jurusan. Pilihan A salah karena biaya kuliah tidak dibahas. Pilihan B salah karena tempat tinggal tidak dibahas. Pilihan D salah karena ia justru menikmati kelas biologi."}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('listening', 'B', 33, $${"kind": "listening", "part": "B", "partTitle": "Part B — Long Conversations", "script": [{"s": "M", "t": "Thanks for seeing me, Professor Alvarez. I'm thinking of switching my major to environmental science."}, {"s": "W", "t": "That's a big decision. What made you consider the switch?"}, {"s": "M", "t": "Honestly, the biology classes I've taken this year have been the highlight of my schedule."}, {"s": "W", "t": "That's a good sign. Have you looked at the required courses for the major?"}, {"s": "M", "t": "A little. I noticed there's a field research component in the junior year."}, {"s": "W", "t": "Right, two weeks at the coastal research station. Most students say it's the best part."}, {"s": "M", "t": "It sounds amazing, but I'm worried about falling behind on credits."}, {"s": "W", "t": "Many of your biology credits will transfer. Why don't we map out a plan together next week?"}], "id": "LIS-B-01-Q4", "scriptId": "LIS-B-01", "stem": "What does the woman suggest?", "options": ["Dropping his biology classes.", "Talking to other students.", "Visiting the research station.", "Planning his courses with her next week."], "answer": 3, "explanation": "Wanita itu mengusulkan Why don't we map out a plan together next week, yaitu menyusun rencana mata kuliah bersama minggu depan. Pilihan A salah karena ia tidak menyarankan berhenti. Pilihan B dan C tidak diusulkan."}$$::jsonb);
INSERT INTO questions (section, part, sort_order, payload) VALUES ('listening', 'B', 34, $${"kind": "listening", "part": "B", "partTitle": "Part B — Long Conversations", "script": [{"s": "W", "t": "Did you see the listing for the apartment on Maple Street?"}, {"s": "M", "t": "Yeah, but it's way out of my budget. I'm looking for something under six hundred a month."}, {"s": "W", "t": "My cousin is moving out of her place next month. It's a two-bedroom, and the rent is pretty reasonable."}, {"s": "M", "t": "How far is it from campus?"}, {"s": "W", "t": "About a fifteen-minute walk. And there's a bus stop right outside."}, {"s": "M", "t": "That sounds perfect. When can I take a look at it?"}, {"s": "W", "t": "She's free this Saturday afternoon. I could go with you if you want."}, {"s": "M", "t": "That would be great. Thanks for thinking of me."}], "id": "LIS-B-02-Q1", "scriptId": "LIS-B-02", "stem": "What are the speakers mainly discussing?", "options": ["A new bus route.", "Looking for an apartment.", "Planning a weekend trip.", "A campus event."], "answer": 1, "explanation": "Percakapan berfokus pada pencarian apartemen untuk pria itu, termasuk anggaran, lokasi, dan jadwal melihat unit sepupu si wanita. Pilihan A salah karena halte bus hanya detail lokasi. Pilihan C dan D tidak dibahas."}$$::jsonb);
